import { Button } from 'moru-ui'
import { ToastProvider, useToast } from 'moru-ui'

function SaveAction() {
  const { toast } = useToast()
  return (
    <Button
      type="button"
      onClick={() =>
        toast({
          title: 'Example notification',
          description: 'Your save action can show its result here.',
          tone: 'success',
          duration: 5000,
        })
      }
    >
      Show notification
    </Button>
  )
}

export function ToastExample() {
  return (
    <ToastProvider>
      <SaveAction />
    </ToastProvider>
  )
}

